/**
 * Frontend helpers for mitigation measure → action → outcome flow.
 */
import type { MitigationAction, MitigationOutcomeSummary, SelectedMitigationAction } from '../types/mitigation';

export const findRecommendationIndex = (
  recommendations: Array<{ title?: string; category?: string }> | undefined,
  rec: { id: string; title: string }
): number => {
  if (!recommendations?.length) return -1;
  return recommendations.findIndex(
    (item, index) =>
      item.title === rec.title ||
      (item.category && item.category === rec.title) ||
      `rec-${index + 1}` === rec.id
  );
};

export const buildMitigationOutcomeSummary = (
  selectedActions: SelectedMitigationAction[] = [],
  implementedCount = 0
): MitigationOutcomeSummary => ({
  selectedActionCount: selectedActions.length,
  estimatedImpactKg: selectedActions.reduce(
    (sum, action) => sum + (Number(action.estimatedImpactKg) || 0),
    0
  ),
  implementedRecommendationCount: implementedCount,
  actualCO2SavedKg: selectedActions.reduce(
    (sum, action) => sum + (Number(action.actualCO2Saved) || 0),
    0
  ),
});

export const mergeSelectedActions = (
  current: SelectedMitigationAction[],
  action: MitigationAction,
  selected: boolean
): SelectedMitigationAction[] => {
  const existing = current.find((item) => item.actionId === action.id);
  if (selected) {
    if (existing) return current;
    return [
      ...current,
      {
        actionId: action.id,
        label: action.label,
        implementationTrack: action.implementationTrack,
        estimatedImpactKg: action.estimatedImpactKg,
        status: 'selected',
        selectedAt: new Date().toISOString(),
      },
    ];
  }
  return current.filter((item) => item.actionId !== action.id);
};
