import React, { useMemo } from 'react';
import { Box, Grid, Paper, Stack, Typography } from '@mui/material';
import { formatCo2eFromKg } from '../../constants/carbonVisualization';
import { resolveCalculationTone, type CalculationTone } from '../../utils/calculationMethodTone';

export type DataQualityCheck = {
  check: string;
  transactions?: number;
  kgCo2e?: number;
};

export type DataQualityTransaction = {
  carbonFootprint?: {
    co2Emissions?: number;
    exclusionReason?: string;
    quantificationMethod?: string;
    calculationMethod?: string;
    dataQualityTier?: string;
    factorLineage?: { id?: string } | null;
    factorId?: string;
    complianceFlags?: string[] | Record<string, boolean>;
  };
  metadata?: { carbonInputBasis?: string };
  validation?: { withinTolerance?: boolean | null };
};

export type DataQualityBoardProps = {
  checks?: DataQualityCheck[];
  excludedCount?: number;
  outsideToleranceCount?: number;
  transactions?: DataQualityTransaction[];
};

type Bucket = {
  id: string;
  label: string;
  note: string;
  count: number;
  kg: number;
};

const checkMatch = (checks: DataQualityCheck[] | undefined, name: string) => (
  (checks || []).find((row) => row.check === name)
);

const toneKg = (tone: CalculationTone | null, transaction: DataQualityTransaction) => {
  if (!tone) return 0;
  return Math.max(0, Number(transaction.carbonFootprint?.co2Emissions) || 0);
};

export const buildDataQualityBuckets = ({
  checks,
  excludedCount,
  outsideToleranceCount,
  transactions = [],
}: DataQualityBoardProps): { methods: Bucket[]; tiers: Array<{ label: string; kg: number }> } => {
  const activityCheck = checkMatch(checks, 'Activity-based');
  const spendCheck = checkMatch(checks, 'Spend-based');
  const estimateCheck = checkMatch(checks, 'Estimate');
  const excludedCheck = checkMatch(checks, 'Excluded');
  const outsideCheck = checkMatch(checks, 'Outside tolerance');
  const hasChecks = Boolean(activityCheck || spendCheck || estimateCheck || excludedCheck || outsideCheck);

  let activity = { count: Number(activityCheck?.transactions) || 0, kg: Number(activityCheck?.kgCo2e) || 0 };
  let spend = { count: Number(spendCheck?.transactions) || 0, kg: Number(spendCheck?.kgCo2e) || 0 };
  let estimate = { count: Number(estimateCheck?.transactions) || 0, kg: Number(estimateCheck?.kgCo2e) || 0 };
  let excluded = {
    count: Number(excludedCheck?.transactions) || Number(excludedCount) || 0,
    kg: Number(excludedCheck?.kgCo2e) || 0,
  };
  let outside = {
    count: Number(outsideCheck?.transactions) || Number(outsideToleranceCount) || 0,
    kg: Number(outsideCheck?.kgCo2e) || 0,
  };

  if (!hasChecks && transactions.length > 0) {
    activity = { count: 0, kg: 0 };
    spend = { count: 0, kg: 0 };
    estimate = { count: 0, kg: 0 };
    excluded = { count: 0, kg: 0 };
    outside = { count: 0, kg: 0 };
    transactions.forEach((transaction) => {
      const kg = Math.max(0, Number(transaction.carbonFootprint?.co2Emissions) || 0);
      if (transaction.carbonFootprint?.exclusionReason) {
        excluded.count += 1;
        excluded.kg += kg;
        return;
      }
      if (transaction.validation?.withinTolerance === false) {
        outside.count += 1;
        outside.kg += kg;
      }
      const tone = resolveCalculationTone(transaction);
      if (tone === 'activity') {
        activity.count += 1;
        activity.kg += toneKg(tone, transaction);
      } else if (tone === 'spend_proxy') {
        spend.count += 1;
        spend.kg += toneKg(tone, transaction);
      } else if (tone === 'estimate') {
        estimate.count += 1;
        estimate.kg += toneKg(tone, transaction);
      }
    });
  }

  const tiers = [
    { label: 'Tier 1 activity', kg: Number(checkMatch(checks, 'Data quality: Tier 1 — activity')?.kgCo2e) || 0 },
    { label: 'Tier 2 spend', kg: Number(checkMatch(checks, 'Data quality: Tier 2 — spend')?.kgCo2e) || 0 },
    { label: 'Tier 3 estimate', kg: Number(checkMatch(checks, 'Data quality: Tier 3 — estimate')?.kgCo2e) || 0 },
  ];

  return {
    methods: [
      { id: 'activity', label: 'Activity-based', note: 'Metered quantity is in the inventory.', ...activity },
      { id: 'spend', label: 'Spend-based', note: 'Rupee spend stands in for a quantity.', ...spend },
      { id: 'estimate', label: 'Estimate-based', note: 'A factor or assumption fills a missing quantity.', ...estimate },
      { id: 'outside', label: 'Outside tolerance', note: 'The calculated kilogram differs from the stored kilogram.', ...outside },
      { id: 'excluded', label: 'Excluded transactions', note: 'Rows kept out of the inventory.', ...excluded },
    ],
    tiers,
  };
};

const DataQualityBoard: React.FC<DataQualityBoardProps> = (props) => {
  const model = useMemo(() => buildDataQualityBuckets(props), [props]);
  const maxKg = Math.max(...model.methods.map((row) => row.kg), 0);
  const tierMax = Math.max(...model.tiers.map((row) => row.kg), 0);

  return (
    <Stack spacing={1.5} data-testid="data-quality-board" id="cf-data-quality">
      <Box>
        <Typography variant="h6" sx={{ fontWeight: 800 }}>Data quality</Typography>
        <Typography variant="body2" color="text.secondary">
          How this inventory was calculated: activity-based, spend-based, and estimate-based rows, plus rows outside tolerance or excluded.
        </Typography>
      </Box>
      <Grid container spacing={1.5}>
        {model.methods.map((row) => (
          <Grid item xs={12} sm={6} lg={4} key={row.id}>
            <Paper variant="outlined" sx={{ p: 1.5, height: '100%' }}>
              <Typography variant="subtitle2" sx={{ fontWeight: 800 }}>{row.label}</Typography>
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>{row.note}</Typography>
              <Typography variant="h6" sx={{ fontWeight: 800 }}>
                {row.count} {row.count === 1 ? 'row' : 'rows'}
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                {formatCo2eFromKg(row.kg)}
              </Typography>
              <Box sx={{ height: 8, borderRadius: 99, bgcolor: 'action.hover' }}>
                <Box
                  sx={{
                    width: `${maxKg > 0 && row.kg > 0 ? Math.max(8, (row.kg / maxKg) * 100) : 0}%`,
                    height: '100%',
                    borderRadius: 99,
                    bgcolor: row.id === 'excluded' || row.id === 'outside' ? '#b45309' : '#0f766e',
                  }}
                />
              </Box>
            </Paper>
          </Grid>
        ))}
      </Grid>
      <Paper variant="outlined" sx={{ p: 1.5 }}>
        <Typography variant="subtitle2" sx={{ fontWeight: 800 }}>Tier split</Typography>
        <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
          Included kilograms by Tier 1 activity, Tier 2 spend, and Tier 3 estimate.
        </Typography>
        {tierMax > 0 ? (
          <Stack spacing={1}>
            {model.tiers.map((row) => (
              <Box key={row.label}>
                <Stack direction="row" justifyContent="space-between">
                  <Typography variant="body2" sx={{ fontWeight: 700 }}>{row.label}</Typography>
                  <Typography variant="caption" color="text.secondary">{formatCo2eFromKg(row.kg)}</Typography>
                </Stack>
                <Box sx={{ mt: 0.4, height: 8, borderRadius: 99, bgcolor: 'action.hover' }}>
                  <Box sx={{ width: `${row.kg > 0 ? Math.max(8, (row.kg / tierMax) * 100) : 0}%`, height: '100%', borderRadius: 99, bgcolor: '#1e3a5f' }} />
                </Box>
              </Box>
            ))}
          </Stack>
        ) : (
          <Typography variant="body2" color="text.secondary">Tier kilograms appear after inventory checks are stored.</Typography>
        )}
      </Paper>
    </Stack>
  );
};

export default DataQualityBoard;
