export const resolveHubSectionLabel = (key: string, locale: ReadinessLocale, fallback = key): string => (
  COMPLIANCE_HUB_SECTION_LABELS[key]?.[locale] || COMPLIANCE_HUB_SECTION_LABELS[key]?.en || fallback
);

export const resolveCarbonTabLabel = (key: string, locale: ReadinessLocale, fallback = key): string => (
  CARBON_TAB_LABELS[key]?.[locale] || CARBON_TAB_LABELS[key]?.en || fallback
);

export const resolveDocumentTabLabel = (key: string, locale: ReadinessLocale, fallback = key): string => (
  DOCUMENT_TAB_LABELS[key]?.[locale] || DOCUMENT_TAB_LABELS[key]?.en || fallback
);

export const resolveTrackItemLabel = (key: string, locale: ReadinessLocale, fallback = key): string => (
  TRACK_ITEM_LABELS[key]?.[locale] || TRACK_ITEM_LABELS[key]?.en || fallback
);

export const resolveReadinessStatusLabel = (
  status: string | undefined,
  locale: ReadinessLocale,
  fallback?: string
): string => {
  const normalized = String(status || '').toLowerCase();
  return READINESS_STATUS_LABELS[normalized]?.[locale]
    || READINESS_STATUS_LABELS[normalized]?.en
    || fallback
    || status
    || 'Unknown';
};
