import React, { useMemo } from 'react';
import { Box, Chip, Grid, Paper, Stack, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import { GHG_SCOPE_COLORS, formatCo2eFromKg } from '../../constants/carbonVisualization';
import {
  resolveScopeCategories,
  SCOPE_PICTURES,
  type ScopePictureKey,
} from '../ghg/scopeCategoryModel';
import { TRI_TILE_GRID } from '../../constants/appShellLayout';

type SubcategoryRow = {
  category?: string;
  subcategory: string;
  kgCo2e: number;
  transactions?: number;
};

export type ScopeInventoryBoardProps = {
  scope1Kg: number;
  scope2Kg: number;
  scope3Kg: number;
  scope1Breakdown?: Record<string, number> | null;
  scope2Breakdown?: Record<string, number> | null;
  scope3Breakdown?: Record<string, number> | null;
  subcategories?: SubcategoryRow[];
};

const SCOPE_META: Array<{ key: ScopePictureKey; title: string; note: string; color: string }> = [
  { key: 'scope1', title: 'Scope 1', note: 'On-site fuel, vehicles, process, and leaks', color: GHG_SCOPE_COLORS.scope1.fill },
  { key: 'scope2', title: 'Scope 2', note: 'Electricity and purchased heat', color: GHG_SCOPE_COLORS.scope2.fill },
  { key: 'scope3', title: 'Scope 3', note: 'Purchases, freight, travel, waste, and water', color: GHG_SCOPE_COLORS.scope3.fill },
];

const ScopeInventoryBoard: React.FC<ScopeInventoryBoardProps> = ({
  scope1Kg,
  scope2Kg,
  scope3Kg,
  scope1Breakdown,
  scope2Breakdown,
  scope3Breakdown,
  subcategories = [],
}) => {
  const kgByScope = { scope1: Math.max(0, scope1Kg), scope2: Math.max(0, scope2Kg), scope3: Math.max(0, scope3Kg) };
  const total = kgByScope.scope1 + kgByScope.scope2 + kgByScope.scope3;
  const unit: 'kg' | 't' = total >= 1000 ? 't' : 'kg';
  const breakdowns = { scope1: scope1Breakdown, scope2: scope2Breakdown, scope3: scope3Breakdown };

  const subcategoryGroups = useMemo(() => {
    const groups = new Map<string, SubcategoryRow[]>();
    subcategories
      .filter((row) => Number(row.kgCo2e) > 0)
      .forEach((row) => {
        const key = row.category || 'Other';
        const list = groups.get(key) || [];
        list.push(row);
        groups.set(key, list);
      });
    return Array.from(groups.entries());
  }, [subcategories]);

  return (
    <Stack spacing={2} data-testid="scope-inventory-board">
      <Paper variant="outlined" sx={{ p: 2 }}>
        <Typography variant="subtitle1" sx={{ fontWeight: 800, mb: 1 }}>
          {total > 0 ? 'Scope split' : 'No scope split yet'}
        </Typography>
        <Stack direction="row" sx={{ height: 18, borderRadius: 99, overflow: 'hidden', bgcolor: 'action.hover' }} aria-label="Scope totals">
          {SCOPE_META.map((scope) => {
            const share = total > 0 ? (kgByScope[scope.key] / total) * 100 : 0;
            if (share <= 0) return null;
            return <Box key={scope.key} sx={{ width: `${share}%`, bgcolor: scope.color }} />;
          })}
        </Stack>
        <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" sx={{ mt: 1.5 }}>
          {SCOPE_META.map((scope) => (
            <Chip
              key={scope.key}
              size="small"
              label={`${scope.title} ${kgByScope[scope.key] > 0 ? formatCo2eFromKg(kgByScope[scope.key], { unit }) : '—'}`}
              sx={{ bgcolor: alpha(scope.color, 0.15), fontWeight: 700 }}
            />
          ))}
        </Stack>
      </Paper>

      <Grid container spacing={2}>
        {SCOPE_META.map((scope) => {
          const categories = resolveScopeCategories(scope.key, breakdowns[scope.key]);
          const scopeKg = kgByScope[scope.key];
          const share = total > 0 ? Math.round((scopeKg / total) * 100) : 0;
          const maxCategory = Math.max(...categories.map((row) => row.kg || 0), 0);
          return (
            <Grid item {...TRI_TILE_GRID} key={scope.key}>
              <Paper variant="outlined" sx={{ p: 2, height: '100%', borderTop: 4, borderTopColor: scope.color }}>
                <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 1 }}>
                  <Box
                    component="img"
                    src={SCOPE_PICTURES[scope.key].src}
                    alt=""
                    sx={{ width: 64, height: 44, objectFit: 'contain', flexShrink: 0 }}
                  />
                  <Box>
                    <Typography variant="h6" sx={{ fontWeight: 800 }}>{scope.title}</Typography>
                    <Typography variant="caption" color="text.secondary">{scope.note}</Typography>
                  </Box>
                </Stack>
                <Typography variant="h5" sx={{ fontWeight: 800 }}>
                  {scopeKg > 0 ? formatCo2eFromKg(scopeKg, { unit }) : '—'}
                </Typography>
                <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1.5 }}>
                  {share > 0 ? `${share}% of this footprint` : 'No emissions in this scope yet'}
                </Typography>
                <Stack spacing={1.25}>
                  {categories.map((category) => {
                    const value = category.kg || 0;
                    const width = maxCategory > 0 && value > 0 ? Math.max(8, (value / maxCategory) * 100) : 0;
                    return (
                      <Box key={category.id}>
                        <Stack direction="row" justifyContent="space-between" spacing={1}>
                          <Typography variant="body2" sx={{ fontWeight: 700 }}>{category.label}</Typography>
                          <Typography variant="caption" color="text.secondary">
                            {value > 0 ? formatCo2eFromKg(value, { unit }) : '—'}
                          </Typography>
                        </Stack>
                        <Box sx={{ mt: 0.5, height: 8, borderRadius: 99, bgcolor: alpha(scope.color, 0.12) }}>
                          <Box sx={{ width: `${width}%`, height: '100%', borderRadius: 99, bgcolor: scope.color }} />
                        </Box>
                      </Box>
                    );
                  })}
                </Stack>
              </Paper>
            </Grid>
          );
        })}
      </Grid>

      {subcategoryGroups.length > 0 ? (
        <Paper variant="outlined" sx={{ p: 2 }}>
          <Typography variant="subtitle1" sx={{ fontWeight: 800, mb: 1.5 }}>
            Sub-categories in this inventory
          </Typography>
          <Stack spacing={2}>
            {subcategoryGroups.map(([category, rows]) => {
              const max = Math.max(...rows.map((row) => row.kgCo2e), 0);
              return (
                <Box key={category}>
                  <Typography variant="body2" sx={{ fontWeight: 800, mb: 1 }}>{category}</Typography>
                  <Stack spacing={1}>
                    {rows.map((row) => (
                      <Stack key={`${category}-${row.subcategory}`} direction="row" spacing={1} alignItems="center">
                        <Typography variant="body2" sx={{ width: { xs: 120, sm: 220 }, flexShrink: 0 }}>
                          {row.subcategory}
                        </Typography>
                        <Box sx={{ flex: 1, height: 10, borderRadius: 99, bgcolor: 'action.hover' }}>
                          <Box
                            sx={{
                              width: `${max > 0 ? Math.max(6, (row.kgCo2e / max) * 100) : 0}%`,
                              height: '100%',
                              borderRadius: 99,
                              bgcolor: '#0f766e',
                            }}
                          />
                        </Box>
                        <Typography variant="caption" sx={{ width: 88, textAlign: 'right' }}>
                          {formatCo2eFromKg(row.kgCo2e, { unit })}
                        </Typography>
                      </Stack>
                    ))}
                  </Stack>
                </Box>
              );
            })}
          </Stack>
        </Paper>
      ) : null}
    </Stack>
  );
};

export default ScopeInventoryBoard;
